html:
{%- set label = label_context(doc) -%}
<style>
	@page { size: 50mm 25mm; margin: 0; }
	.print-format { width: 50mm !important; min-height: 0 !important; padding: 0 !important; margin: 0 !important; }
	.sf-label { width: 50mm; height: 25mm; box-sizing: border-box; padding: 1.2mm 2mm 1mm; overflow: hidden;
		font-family: Arial, Helvetica, sans-serif; color: #000; page-break-after: always; }
	.sf-label:last-child { page-break-after: auto; }
	.sf-label .top { display: flex; justify-content: space-between; align-items: flex-start; line-height: 1.1; }
	.sf-label .uom { font-size: 7.5pt; font-weight: 700; }
	.sf-label .price { text-align: right; font-size: 7.5pt; font-weight: 700; }
	.sf-label .price .ar { font-weight: 400; direction: rtl; }
	.sf-label .bars { height: 9mm; margin: 0.6mm 2mm 0; }
	.sf-label .code { text-align: center; font-size: 7.5pt; font-weight: 700; letter-spacing: 0.4pt; line-height: 1.1; }
	.sf-label .name { text-align: center; font-size: 6.5pt; font-weight: 700; line-height: 1.1; max-height: 2.2em; overflow: hidden; }
</style>
{%- for copy in range(label.copies) %}
<div class="sf-label">
	<div class="top">
		<div class="uom">{{ label.uom }}</div>
		{%- if label.price %}
		<div class="price">{{ label.price.english }}<br><span class="ar">{{ label.price.arabic }}</span></div>
		{%- endif %}
	</div>
	<div class="bars">{{ label.barcode }}</div>
	<div class="code">{{ label.code }}</div>
	<div class="name">{{ label.name }}</div>
</div>
{%- endfor %}
